import { PrismaClient } from "@prisma/client";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { Badge } from "@/components/ui/badge";

const prisma = new PrismaClient();

// In Next.js 15, we can use searchParams, but to keep it simple, we just list the upcoming ones.
export default async function AppointmentsPage() {
  const bookings = await prisma.booking.findMany({
    include: {
      patient: true,
      professional: true,
      service: true,
    },
    orderBy: [{ date: "desc" }, { startTime: "desc" }],
    take: 50,
  });

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Agendamentos</h1>
        <p className="text-zinc-500 dark:text-zinc-400 mt-2">
          Hist├│rico e pr├│ximos agendamentos da cl├¡nica.
        </p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Todos os Agendamentos</CardTitle>
          <CardDescription>Mostrando os ├║ltimos 50 registros.</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-zinc-500 uppercase bg-zinc-50 dark:bg-zinc-900 border-b border-zinc-200 dark:border-zinc-800">
                <tr>
                  <th className="px-6 py-3 font-medium">Data & Hora</th>
                  <th className="px-6 py-3 font-medium">Paciente</th>
                  <th className="px-6 py-3 font-medium">Servi├ºo</th>
                  <th className="px-6 py-3 font-medium">Profissional</th>
                  <th className="px-6 py-3 font-medium">Status</th>
                </tr>
              </thead>
              <tbody>
                {bookings.length === 0 && (
                  <tr>
                    <td
                      colSpan={5}
                      className="px-6 py-4 text-center text-zinc-500"
                    >
                      Nenhum agendamento encontrado.
                    </td>
                  </tr>
                )}
                {bookings.map((booking) => {
                  const isFuture =
                    booking.date >= new Date(new Date().setHours(0, 0, 0, 0));

                  return (
                    <tr
                      key={booking.id}
                      className="border-b border-zinc-100 dark:border-zinc-800 last:border-0 hover:bg-zinc-50/50 dark:hover:bg-zinc-900/50 transition-colors"
                    >
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="font-medium text-zinc-900 dark:text-zinc-100">
                          {format(booking.date, "dd/MM/yyyy")}
                        </div>
                        <div className="text-zinc-500">{booking.startTime}</div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="font-medium">
                          {booking.patient.name}
                        </div>
                        <div className="text-xs text-zinc-500">
                          {booking.patient.phone}
                        </div>
                      </td>
                      <td className="px-6 py-4 text-zinc-600 dark:text-zinc-300">
                        {booking.service.name}
                      </td>
                      <td className="px-6 py-4">{booking.professional.name}</td>
                      <td className="px-6 py-4">
                        {booking.status === "CONFIRMED" ? (
                          <Badge
                            variant="outline"
                            className={
                              isFuture
                                ? "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-900/50 dark:bg-emerald-900/20 dark:text-emerald-400"
                                : "text-zinc-500"
                            }
                          >
                            {isFuture ? "Confirmado" : "Realizado"}
                          </Badge>
                        ) : (
                          <Badge variant="destructive">Cancelado</Badge>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";

type User = {
  id: string;
  name: string;
  email: string;
  role: string;
  createdAt: string;
};

export default function UsersPage() {
  const [users, setUsers] = useState<User[]>([]);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);

  // Form State
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("ATENDENTE");

  const fetchUsers = async () => {
    const res = await fetch("/api/users");
    if (res.ok) setUsers(await res.json());
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleOpenDialog = (user?: User) => {
    if (user) {
      setEditingUserId(user.id);
      setName(user.name);
      setEmail(user.email);
      setRole(user.role);
      setPassword(""); // Don't show existing password
    } else {
      setEditingUserId(null);
      setName("");
      setEmail("");
      setPassword("");
      setRole("ATENDENTE");
    }
    setIsDialogOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const isEditing = !!editingUserId;
      const url = isEditing ? `/api/users/${editingUserId}` : "/api/users";
      const method = isEditing ? "PUT" : "POST";

      const payload: any = { name, email, role };
      if (password) payload.password = password;

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        setIsDialogOpen(false);
        fetchUsers();
      } else {
        const errorData = await res.json();
        alert(errorData.error || "Erro ao salvar usu├írio.");
      }
    } catch {
      alert("Falha na comunica├º├úo.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Tem certeza que deseja remover este usu├írio?")) return;

    try {
      const res = await fetch(`/api/users/${id}`, { method: "DELETE" });
      if (res.ok) {
        fetchUsers();
      } else {
        const errorData = await res.json();
        alert(errorData.error || "Erro ao deletar usu├írio.");
      }
    } catch {
      alert("Erro na requisi├º├úo.");
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">
            Usu├írios do Sistema
          </h1>
          <p className="text-zinc-500 dark:text-zinc-400 mt-2">
            Gerencie os administradores e atendentes da cl├¡nica.
          </p>
        </div>
        <Button onClick={() => handleOpenDialog()}>Novo Usu├írio</Button>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Equipe</CardTitle>
          <CardDescription>
            Lista de membros com acesso ao painel.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-zinc-500 uppercase bg-zinc-50 dark:bg-zinc-900 border-b border-zinc-200 dark:border-zinc-800">
                <tr>
                  <th className="px-6 py-3 font-medium">Nome</th>
                  <th className="px-6 py-3 font-medium">E-mail</th>
                  <th className="px-6 py-3 font-medium">Acesso</th>
                  <th className="px-6 py-3 font-medium text-right">A├º├Áes</th>
                </tr>
              </thead>
              <tbody>
                {users.length === 0 && (
                  <tr>
                    <td
                      colSpan={4}
                      className="px-6 py-4 text-center text-zinc-500"
                    >
                      Nenhum registro encontrado.
                    </td>
                  </tr>
                )}
                {users.map((user) => (
                  <tr
                    key={user.id}
                    className="border-b border-zinc-100 dark:border-zinc-800 last:border-0 hover:bg-zinc-50/50 dark:hover:bg-zinc-900/50 transition-colors"
                  >
                    <td className="px-6 py-4 font-medium text-zinc-900 dark:text-zinc-100">
                      {user.name}
                    </td>
                    <td className="px-6 py-4 text-zinc-600 dark:text-zinc-300">
                      {user.email}
                    </td>
                    <td className="px-6 py-4">
                      <Badge
                        variant="outline"
                        className={
                          user.role === "ADMIN"
                            ? "border-indigo-200 bg-indigo-50 text-indigo-700 dark:border-indigo-900/50 dark:bg-indigo-900/20 dark:text-indigo-400"
                            : "text-zinc-500"
                        }
                      >
                        {user.role}
                      </Badge>
                    </td>
                    <td className="px-6 py-4 text-right space-x-3">
                      <button
                        onClick={() => handleOpenDialog(user)}
                        className="text-emerald-600 hover:underline"
                      >
                        Editar
                      </button>
                      <button
                        onClick={() => handleDelete(user.id)}
                        className="text-red-500 hover:underline"
                      >
                        Remover
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle>
              {editingUserId ? "Editar Usu├írio" : "Novo Usu├írio"}
            </DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="name">Nome completo</Label>
              <Input
                id="name"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="email">E-mail</Label>
              <Input
                id="email"
                type="email"
                required={!editingUserId}
                disabled={!!editingUserId}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">
                Senha {editingUserId && "(Deixe em branco para n├úo alterar)"}
              </Label>
              <Input
                id="password"
                type="password"
                required={!editingUserId}
                minLength={4}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="role">N├¡vel de Acesso</Label>
              <Select value={role} onValueChange={setRole}>
                <SelectTrigger>
                  <SelectValue placeholder="Selecione um n├¡vel" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ATENDENTE">Atendente</SelectItem>
                  <SelectItem value="ADMIN">Administrador</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <DialogFooter className="pt-4">
              <Button type="submit" disabled={isSubmitting} className="w-full">
                {isSubmitting ? "Salvando..." : "Salvar Usu├írio"}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { NextResponse } from "next/server";
import { PrismaClient } from "@prisma/client";
import { auth } from "@/auth";

const prisma = new PrismaClient();

export async function PUT(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const session = await auth();
    if (!session) {
      return NextResponse.json({ error: "Acesso negado" }, { status: 403 });
    }

    const { id } = await params;
    const { status } = await req.json();

    const booking = await prisma.booking.update({
      where: { id },
      data: { status },
      include: { patient: true, professional: true, service: true },
    });

    return NextResponse.json(booking);
  } catch (error) {
    return NextResponse.json({ error: "Erro ao atualizar" }, { status: 500 });
  }
}

export async function DELETE(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const session = await auth();
    // Only ADMIN or ATENDENTE can delete the record physically (usually we just cancel)
    if (!session) {
      return NextResponse.json({ error: "Acesso negado" }, { status: 403 });
    }

    const { id } = await params;
    await prisma.booking.delete({
      where: { id },
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    return NextResponse.json({ error: "Erro ao deletar" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { PrismaClient } from "@prisma/client";
import { auth } from "@/auth";
import { addMinutes, format, parse } from "date-fns";

const prisma = new PrismaClient();

// Protected: Get all bookings (Admin/Atendente)
export async function GET() {
  try {
    const session = await auth();
    if (!session) {
      return NextResponse.json({ error: "Acesso negado" }, { status: 403 });
    }

    const bookings = await prisma.booking.findMany({
      include: {
        patient: true,
        professional: true,
        service: true,
      },
      orderBy: [{ date: "asc" }, { startTime: "asc" }],
    });

    return NextResponse.json(bookings);
  } catch (error) {
    return NextResponse.json({ error: "Falha ao processar" }, { status: 500 });
  }
}

// Public: Create a new booking
export async function POST(req: Request) {
  try {
    const {
      professionalId,
      serviceId,
      dateStr,
      startTime,
      name,
      phone,
      email,
    } = await req.json();

    if (
      !professionalId ||
      !serviceId ||
      !dateStr ||
      !startTime ||
      !name ||
      !phone
    ) {
      return NextResponse.json({ error: "Dados incompletos" }, { status: 400 });
    }

    const service = await prisma.service.findUnique({
      where: { id: serviceId },
    });
    if (!service)
      return NextResponse.json({ error: "Servi├ºo inv├ílido" }, { status: 404 });

    const date = new Date(`${dateStr}T00:00:00.000-03:00`);
    const parsedStart = parse(startTime, "HH:mm", date);
    const endTime = format(addMinutes(parsedStart, service.duration), "HH:mm");

    // Extra layer of validation could call our availability logic again here
    // But for MVP, we just create the record directly against DB transaction constraints if possible.

    // Check direct overlaps defensively
    const overlaps = await prisma.booking.findFirst({
      where: {
        professionalId,
        date: {
          gte: new Date(`${dateStr}T00:00:00.000-03:00`),
          lte: new Date(`${dateStr}T23:59:59.999-03:00`),
        },
        status: { not: "CANCELLED" },
        AND: [{ startTime: { lt: endTime } }, { endTime: { gt: startTime } }],
      },
    });

    if (overlaps) {
      return NextResponse.json(
        { error: "Hor├írio j├í reservado." },
        { status: 409 },
      );
    }

    // Upsert Patient (Match by WhatsApp/Phone)
    const patient = await prisma.patient.upsert({
      where: { phone },
      update: { name, email }, // Update details if needed
      create: { name, phone, email },
    });

    const booking = await prisma.booking.create({
      data: {
        date,
        startTime,
        endTime,
        status: "CONFIRMED",
        professionalId,
        serviceId,
        patientId: patient.id,
      },
    });

    return NextResponse.json(booking, { status: 201 });
  } catch (error) {
    console.error("Booking Error:", error);
    return NextResponse.json({ error: "Erro ao agendar" }, { status: 500 });
  }
}

